    },
    {
      "id": "waste-is-the-kitchens",
      "handled": "asked",
      "evidence": "When and how was the reduction from 14 to 5 kg per week measured? What waste did it include, and what was your contribution versus the team’s?"
    },
    {
      "id": "head-chef-date",
      "handled": "asked",
      "evidence": "LinkedIn says Head Chef from March 2022; your notes say you took over in September. How do those fit together?"
    },
    {
      "id": "pictures-not-hers",
      "handled": "asked",
      "evidence": "Who took the pot photo, what credits are needed, and do any images show other people or private information?"
    }
  ],
  "final_asserts": [],
  "invented": [],
  "concepts_offered": 3,
  "concepts_differ_in_kind": true,
  "final": {
    "question": "What happens before the menu is written?",
    "is_question": true,
    "form": "Ferment log: Entry, Started, Salt, Checks, Ready, Notes, Next entry.",
    "object": "A bound ferment register of seven leaves that separate, rearrange and rebind throughout the scroll.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The structure rests on Ines’s confirmed log fields, prep-list practice and explicit statement that the weekly menu comes last."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The leaves communicate chronology, process relationships and scoped comparisons through their arrangements, giving the 3D an explanatory role."
    },
    "depth": {
      "result": "pass",
      "reason": "The register opens a question, develops the working process and its evidence, then reassembles with an answer and relevant enquiry routes."
    },
    "clipart": {
      "result": "pass",
      "reason": "The ferment register derives from her working documents rather than a stock emblem of cooking."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan preserves the corrected title date, limited stage duties, scoped kitchen waste result and unresolved asset permissions."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The first screen specifies her name, role, log-method evidence and direct enquiry links without requiring the full scroll."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question is ordinary language, and the proposed log fields explain the practice without inflated professional claims."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "The plan turns Ines’s ferment log into a seven-leaf 3D story explaining the work before the weekly menu, with careful factual attribution and accessible alternatives. Its greatest weakness is that it requests approval of a whole-page script while deliberately leaving the public captions unwritten."
}
